def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def term(depth):
        if depth > 0 and rng.random() < 0.35:
            return '(' + expr(depth - 1) + ')'
        return '*'.join(rng.choice(letters) for _ in range(rng.choice((1, 1, 2, 3))))
    def expr(depth):
        k = rng.randint(1, 4)
        s = term(depth)
        for _ in range(k - 1):
            s += rng.choice('+-') + term(depth)
        return s
    def spaced(s):
        return ''.join((' ' + c if c in '+-' and rng.random() < 0.5 else c) for c in s)
    def long_expr(target, cap, po, pc):
        out = []
        depth = 0
        L = 0
        while True:
            while rng.random() < po and depth < cap:
                out.append('(')
                depth += 1
                L += 1
            k = rng.randint(1, 3)
            out.append('*'.join(rng.choice(letters) for _ in range(k)))
            L += 2 * k - 1
            while depth > 0 and rng.random() < pc:
                out.append(')')
                depth -= 1
                L += 1
            if L >= target:
                out.append(')' * depth)
                break
            out.append(rng.choice('+-'))
            L += 1
        return ''.join(out)
    tests = ['a', '(a)', '(a-(b+c)+d)', 'a-(b-c)', '(p*p) - (a-b)', 'a-b-c', '((a))', '-'.join('(x+y)' for _ in range(3)).replace('-', '+', 1)]
    tests.append('a-(b-(c-(d-(e-f))))')
    tests.append('a*b-(c*d+e*f*g)')
    for d in (1, 2, 3, 4):
        for _ in range(5):
            e = expr(d)
            tests.append(spaced(e) if rng.random() < 0.4 else e)
    for _ in range(4):
        tests.append(long_expr(60, 6, 0.4, 0.4))
    tests.append('(a-' * 5000 + 'a' + ')' * 5000)
    tests.append('(a+' * 3000 + 'b-(' * 1000 + 'c' + ')' * 4000)
    tests.append(long_expr(200000, 5000, 0.3, 0.3))
    tests.append(long_expr(200000, 50, 0.45, 0.45))
    tests.append(long_expr(200000, 5000, 0.15, 0.02))
    tests.append(spaced(long_expr(150000, 5000, 0.2, 0.2)))
    return tests
